// 計算 nums 的每個長為 k 的視窗的最大值
// 時間複雜度 O(n)，其中 n 是 nums 的長度
vector<int> maxSlidingWindow(const vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> ans(n - k + 1); // 視窗個數
    deque<int> q; // 雙端佇列

    for (int i = 0; i < n; i++) {
        // 1. 右邊入
        while (!q.empty() && nums[q.back()] <= nums[i]) {
            q.pop_back(); // 維護 q 的單調性
        }
        q.push_back(i); // 注意儲存的是下標，這樣下面可以判斷隊首是否離開視窗

        // 2. 左邊出
        int left = i - k + 1; // 視窗左端點
        if (q.front() < left) { // 隊首離開視窗
            q.pop_front();
        }

        // 3. 在視窗左端點處記錄答案
        if (left >= 0) {
            // 由於隊首到隊尾單調遞減，所以視窗最大值就在隊首
            ans[left] = nums[q.front()];
        }
    }

    return ans;
}
