```go [sol-Go]
// 計算 nums 的每個長為 k 的視窗的最大值
// 時間複雜度 O(n)，其中 n 是 nums 的長度
func maxSlidingWindow(nums []int, k int) []int {
    ans := make([]int, len(nums)-k+1) // 視窗個數
    q := []int{}

    for i, x := range nums {
        // 1. 右邊入
        for len(q) > 0 && nums[q[len(q)-1]] <= x {
            q = q[:len(q)-1] // 維護 q 的單調性
        }
        q = append(q, i) // 注意儲存的是下標，這樣下面可以判斷隊首是否離開視窗

        // 2. 左邊出
        left := i - k + 1 // 視窗左端點
        if q[0] < left {  // 隊首離開視窗
            q = q[1:] // Go 的切片是 O(1) 的
        }

        // 3. 在視窗左端點處記錄答案
        if left >= 0 {
            // 由於隊首到隊尾單調遞減，所以視窗最大值就在隊首
            ans[left] = nums[q[0]]
        }
    }

    return ans
}
```

