支援刪除堆中任意元素。

模板：

```py [sol-Python3]
# 模板來源 https://leetcode.cn/discuss/post/3583665/
class LazyHeap:
    def __init__(self):
        self.heap = []  # 最小堆（最大堆可以把數字取反或過載 __lt__）
        self.remove_cnt = defaultdict(int)  # 每個元素剩餘需要刪除的次數
        self.size = 0  # 堆的實際大小

    # 刪除
    def remove(self, x: Any) -> None:
        self.remove_cnt[x] += 1  # 懶刪除
        self.size -= 1

    # 正式執行刪除操作
    def _apply_remove(self) -> None:
        while self.heap and self.remove_cnt[self.heap[0]] > 0:
            self.remove_cnt[self.heap[0]] -= 1
            heappop(self.heap)

    # 檢視堆頂
    def top(self) -> Any:
        self._apply_remove()
        return self.heap[0]  # 真正的堆頂

    # 出堆
    def pop(self) -> Any:
        self._apply_remove()
        self.size -= 1
        return heappop(self.heap)

    # 入堆
    def push(self, x: Any) -> None:
        if self.remove_cnt[x] > 0:
            self.remove_cnt[x] -= 1  # 抵消之前的刪除
        else:
            heappush(self.heap, x)
        self.size += 1
```

```java [sol-Java]
// 模板來源 https://leetcode.cn/discuss/post/3583665/
// 最小堆 LazyHeap minPQ = new LazyHeap(Integer::compare);
// 最大堆 LazyHeap maxPQ = new LazyHeap((a, b) -> Integer.compare(b, a));
class LazyHeap extends PriorityQueue<Integer> {
    private final Map<Integer, Integer> removeCnt = new HashMap<>(); // 每個元素剩餘需要刪除的次數
    private int size = 0; // 堆的實際大小

    public LazyHeap(Comparator<Integer> comparator) {
        super(comparator);
    }

    // 刪除堆中所有應該刪除的元素後，堆的實際大小
    public int size() {
        return size;
    }

    // 刪除
    public void remove(int x) {
        removeCnt.merge(x, 1, Integer::sum); // 懶刪除
        size--;
    }

    // 正式執行刪除操作
    private void applyRemove() {
        while (removeCnt.getOrDefault(peek(), 0) > 0) {
            removeCnt.merge(poll(), -1, Integer::sum);
        }
    }

    // 檢視堆頂
    public int top() {
        applyRemove();
        return peek(); // 真正的堆頂
    }

    // 出堆
    public int pop() {
        applyRemove();
        size--;
        return poll();
    }

    // 入堆
    public void push(int x) {
        int c = removeCnt.getOrDefault(x, 0);
        if (c > 0) {
            removeCnt.put(x, c - 1); // 抵消之前的刪除
        } else {
            offer(x);
        }
        size++;
    }
}
```

```cpp [sol-C++]
// 模板來源 https://leetcode.cn/discuss/post/3583665/
// 最大堆 LazyHeap<int> max_pq;
// 最小堆 LazyHeap<int, greater<>> min_pq;
template<typename T, typename Compare = less<T>>
class LazyHeap {
    priority_queue<T, vector<T>, Compare> pq;
    unordered_map<T, int> remove_cnt; // 每個元素剩餘需要刪除的次數
    size_t sz = 0; // 堆的實際大小

    // 正式執行刪除操作
    void apply_remove() {
        while (!pq.empty() && remove_cnt[pq.top()] > 0) {
            remove_cnt[pq.top()]--;
            pq.pop();
        }
    }

public:
    // 刪除堆中所有應該刪除的元素後，堆的實際大小
    size_t size() {
        return sz;
    }

    // 刪除
    void remove(T x) {
        remove_cnt[x]++; // 懶刪除
        sz--;
    }

    // 檢視堆頂
    T top() {
        apply_remove();
        return pq.top(); // 真正的堆頂
    }

    // 出堆
    T pop() {
        apply_remove();
        sz--;
        T x = pq.top();
        pq.pop();
        return x;
    }

    // 入堆
    void push(T x) {
        if (remove_cnt[x] > 0) {
            remove_cnt[x]--; // 抵消之前的刪除
        } else {
            pq.push(x);
        }
        sz++;
    }
};
