```py [sol-Python3]
# 模板來源 https://leetcode.cn/discuss/post/3583665/
class UnionFind:
    def __init__(self, n: int):
        # 一開始有 n 個集合 {0}, {1}, ..., {n-1}
        # 集合 i 的代表元是自己，自己到自己的距離是 0
        self.fa = list(range(n))  # 代表元
        self.dis = [0] * n  # dis[x] 表示 x 到（x 所在集合的）代表元的距離

    # 返回 x 所在集合的代表元
    # 同時做路徑壓縮
    def find(self, x: int) -> int:
        fa = self.fa
        if fa[x] != x:
            root = self.find(fa[x])
            self.dis[x] += self.dis[fa[x]]  # 遞迴更新 x 到其代表元的距離
            fa[x] = root
        return fa[x]

    # 判斷 x 和 y 是否在同一個集合（同普通並查集）
    def same(self, x: int, y: int) -> bool:
        return self.find(x) == self.find(y)

    # 計算從 from 到 to 的相對距離
    # 呼叫時需保證 from 和 to 在同一個集合中，否則返回值無意義
    def get_relative_distance(self, from_: int, to: int) -> int:
        self.find(from_)
        self.find(to)
        # to-from = (x-from) - (x-to) = dis[from] - dis[to]
        return self.dis[from_] - self.dis[to]

    # 合併 from 和 to，新增資訊 to - from = value
    # 其中 to 和 from 表示未知量，下文的 x 和 y 也表示未知量
    # 如果 from 和 to 不在同一個集合，返回 True，否則返回是否與已知資訊矛盾
    def merge(self, from_: int, to: int, value: int) -> bool:
        x, y = self.find(from_), self.find(to)
        dis = self.dis
        if x == y:  # from 和 to 在同一個集合，不做合併
            # to-from = (x-from) - (x-to) = dis[from] - dis[to] = value
            return dis[from_] - dis[to] == value
        #    x --------- y
        #   /           /
        # from ------- to
        # 已知 x-from = dis[from] 和 y-to = dis[to]，現在合併 from 和 to，新增資訊 to-from = value
        # 由於 y-from = (y-x) + (x-from) = (y-to) + (to-from)
        # 所以 y-x = (to-from) + (y-to) - (x-from) = value + dis[to] - dis[from]
        dis[x] = value + dis[to] - dis[from_]  # 計算 x 到其代表元 y 的距離
        self.fa[x] = y
        return True
```

```java [sol-Java]
// 模板來源 https://leetcode.cn/discuss/post/3583665/
class UnionFind {
    private final int[] fa; // 代表元
    private final int[] dis; // dis[x] 表示 x 到（x 所在集合的）代表元的距離
    // 注意資料範圍，必要時使用 long[] dis

    public UnionFind(int n) {
        // 一開始有 n 個集合 {0}, {1}, ..., {n-1}
        // 集合 i 的代表元是自己，自己到自己的距離是 0
        fa = new int[n];
        dis = new int[n];
        for (int i = 0; i < n; i++) {
            fa[i] = i;
        }
    }

    // 返回 x 所在集合的代表元
    // 同時做路徑壓縮
    public int find(int x) {
        if (fa[x] != x) {
            int root = find(fa[x]);
            dis[x] += dis[fa[x]]; // 遞迴更新 x 到其代表元的距離
            fa[x] = root;
        }
        return fa[x];
    }

    // 判斷 x 和 y 是否在同一個集合（同普通並查集）
    public boolean same(int x, int y) {
        return find(x) == find(y);
    }

    // 計算從 from 到 to 的相對距離
    // 呼叫時需保證 from 和 to 在同一個集合中，否則返回值無意義
    public int getRelativeDistance(int from, int to) {
        find(from);
        find(to);
        // to-from = (x-from) - (x-to) = dis[from] - dis[to]
        return dis[from] - dis[to];
    }

    // 合併 from 和 to，新增資訊 to - from = value
    // 其中 to 和 from 表示未知量，下文的 x 和 y 也表示未知量
    // 如果 from 和 to 不在同一個集合，返回 true，否則返回是否與已知資訊矛盾
    public boolean merge(int from, int to, int value) {
        int x = find(from), y = find(to);
        if (x == y) { // from 和 to 在同一個集合，不做合併
            // to-from = (x-from) - (x-to) = dis[from] - dis[to] = value
            return dis[from] - dis[to] == value;
        }
        //    x --------- y
        //   /           /
        // from ------- to
        // 已知 x-from = dis[from] 和 y-to = dis[to]，現在合併 from 和 to，新增資訊 to-from = value
        // 由於 y-from = (y-x) + (x-from) = (y-to) + (to-from)
        // 所以 y-x = (to-from) + (y-to) - (x-from) = value + dis[to] - dis[from]
        dis[x] = value + dis[to] - dis[from]; // 計算 x 到其代表元 y 的距離
        fa[x] = y;
        return true;
    }
}
