    }

    // 判斷 x 和 y 是否在同一個集合（同普通並查集）
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    // 計算從 from 到 to 的相對距離
    // 呼叫時需保證 from 和 to 在同一個集合中，否則返回值無意義
    T get_relative_distance(int from, int to) {
        find(from);
        find(to);
        // to-from = (x-from) - (x-to) = dis[from] - dis[to]
        return dis[from] - dis[to];
    }

    // 合併 from 和 to，新增資訊 to - from = value
    // 其中 to 和 from 表示未知量，下文的 x 和 y 也表示未知量
    // 如果 from 和 to 不在同一個集合，返回 true，否則返回是否與已知資訊矛盾
    bool merge(int from, int to, T value) {
        int x = find(from), y = find(to);
        if (x == y) { // from 和 to 在同一個集合，不做合併
            // to-from = (x-from) - (x-to) = dis[from] - dis[to] = value
            return dis[from] - dis[to] == value;
        }
        //    x --------- y
        //   /           /
        // from ------- to
        // 已知 x-from = dis[from] 和 y-to = dis[to]，現在合併 from 和 to，新增資訊 to-from = value
        // 由於 y-from = (y-x) + (x-from) = (y-to) + (to-from)
        // 所以 y-x = (to-from) + (y-to) - (x-from) = value + dis[to] - dis[from]
        dis[x] = value + dis[to] - dis[from]; // 計算 x 到其代表元 y 的距離
        fa[x] = y;
        return true;
    }
};
