```py [sol-Python3]
# 模板來源 https://leetcode.cn/discuss/post/3583665/
class FenwickTree:
    def __init__(self, n: int):
        self.tree = [0] * (n + 1)  # 使用下標 1 到 n

    # a[i] 增加 val
    # 1 <= i <= n
    # 時間複雜度 O(log n)
    def update(self, i: int, val: int) -> None:
        t = self.tree
        while i < len(t):
            t[i] += val
            i += i & -i

    # 計算字首和 a[1] + ... + a[i]
    # 1 <= i <= n
    # 時間複雜度 O(log n)
    def pre(self, i: int) -> int:
        t = self.tree
        res = 0
        while i > 0:
            res += t[i]
            i &= i - 1
        return res

    # 計算區間和 a[l] + ... + a[r]
    # 1 <= l <= r <= n
    # 時間複雜度 O(log n)
    def query(self, l: int, r: int) -> int:
        if l > r:
            return 0
        return self.pre(r) - self.pre(l - 1)
```

