**模板二：值域樹狀陣列**

```py [sol-Python3]
# 應用：https://leetcode.cn/problems/maximum-subarray-sum-after-at-most-k-swaps/
class FenwickTree:
    def __init__(self, sorted_nums: list[int]):
        self.n = n = len(sorted_nums)
        self.high_bit = 1 << (n.bit_length() - 1)
        self.sorted_nums = sorted_nums
        self.cnt = [0] * (n + 1)
        self.sum = [0] * (n + 1)

    # 新增 num 個 val，其中 val 離散化後的值為 i（i 從 1 開始）
    # 如果 num < 0，表示減少 -num 個 val
    # 注意 val = sorted_nums[i - 1]，無需手動傳入
    def update(self, i: int, num: int) -> None:
        val = self.sorted_nums[i - 1]
        while i <= self.n:
            self.cnt[i] += num
            self.sum[i] += num * val
            i += i & -i

    # 返回第 k 小的數（k 從 1 開始）
    # 如果不存在第 k 小的數，while 迴圈後的 i = self.n，下標越界
    def kth(self, k: int) -> int:
        i = 0
        b = self.high_bit
        while b > 0:
            nxt = i | b
            if nxt <= self.n and self.cnt[nxt] < k:
                k -= self.cnt[nxt]
                i = nxt
            b >>= 1
        return self.sorted_nums[i]

    # 返回前 k 小的數之和（k 從 1 開始）
    # 如果不存在第 k 小的數，while 迴圈後的 i = self.n，下標越界
    def pre_sum(self, k: int) -> int:
        s = i = 0
        b = self.high_bit
        while b > 0:
            nxt = i | b
            if nxt <= self.n and self.cnt[nxt] < k:
                k -= self.cnt[nxt]
                s += self.sum[nxt]
                i = nxt
            b >>= 1
        # 加上等於第 k 小的數
        return s + self.sorted_nums[i] * k
```

```java [sol-Java]
// 應用：https://leetcode.cn/problems/maximum-subarray-sum-after-at-most-k-swaps/
class FenwickTree {
    private final int highBit;
    private final int[] sorted;
    private final int[] cnt;
    private final long[] sum;

    public FenwickTree(int[] sorted) {
        int n = sorted.length;
        highBit = Integer.highestOneBit(n);
        this.sorted = sorted;
        cnt = new int[n + 1];
        sum = new long[n + 1];
    }

    // 新增 num 個 val，其中 val 離散化後的值為 i（i 從 1 開始）
    // 如果 num < 0，表示減少 -num 個 val
    // 注意 val = sorted[i - 1]，無需手動傳入
    public void update(int i, int num) {
        int val = sorted[i - 1];
        for (; i < cnt.length; i += i & -i) {
            cnt[i] += num;
            sum[i] += (long) num * val;
        }
    }

    // 返回第 k 小的數（k 從 1 開始）
    // 如果不存在第 k 小的數，for 迴圈後的 i = sorted.length，下標越界
    public int kth(int k) {
        int i = 0;
        for (int b = highBit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.length && cnt[nxt] < k) {
                k -= cnt[nxt];
                i = nxt;
            }
        }
        return sorted[i];
    }

    // 返回前 k 小的數之和（k 從 1 開始）
    // 如果不存在第 k 小的數，for 迴圈後的 i = sorted.length，下標越界
    public long preSum(int k) {
        long s = 0;
        int i = 0;
        for (int b = highBit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.length && cnt[nxt] < k) {
                k -= cnt[nxt];
                s += sum[nxt];
                i = nxt;
            }
        }
        // 加上等於第 k 小的數
        return s + (long) sorted[i] * k;
    }
}
