```cpp [sol-C++]
// 應用：https://leetcode.cn/problems/maximum-subarray-sum-after-at-most-k-swaps/
class FenwickTree {
    const vector<int>& sorted;
    const int high_bit;
    vector<int> cnt;
    vector<long long> sum;

public:
    FenwickTree(const vector<int>& sorted) :
        sorted(sorted),
        high_bit(1 << (bit_width(sorted.size()) - 1)),
        cnt(sorted.size() + 1),
        sum(sorted.size() + 1) {}

    // 新增 num 個 val，其中 val 離散化後的值為 i（i 從 1 開始）
    // 如果 num < 0，表示減少 -num 個 val
    // 注意 val = sorted[i - 1]，無需手動傳入
    void update(int i, int num) {
        auto val = sorted[i - 1];
        for (; i < cnt.size(); i += i & -i) {
            cnt[i] += num;
            sum[i] += 1LL * num * val;
        }
    }

    // 返回第 k 小的數（k 從 1 開始）
    // 如果不存在第 k 小的數，for 迴圈後的 i = sorted.size()，下標越界
    int kth(int k) const {
        int i = 0;
        for (int b = high_bit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.size() && cnt[nxt] < k) {
                k -= cnt[nxt];
                i = nxt;
            }
        }
        return sorted[i];
    }

    // 返回前 k 小的數之和（k 從 1 開始）
    // 如果不存在第 k 小的數，for 迴圈後的 i = sorted.size()，下標越界
    long long pre_sum(int k) const {
        long long s = 0;
        int i = 0;
        for (int b = high_bit; b > 0; b >>= 1) {
            int nxt = i | b;
            if (nxt < cnt.size() && cnt[nxt] < k) {
                k -= cnt[nxt];
                s += sum[nxt];
                i = nxt;
            }
        }
        // 加上等於第 k 小的數
        return s + 1LL * sorted[i] * k;
    }
};
