type pair struct{ cnt, sum int }
type fenwick struct {
	t       []pair
	sorted  []int
	highBit int
}

func newFenwickTree(sorted []int) fenwick {
	n := len(sorted)
	return fenwick{
		t:       make([]pair, n+1),
		sorted:  sorted,
		highBit: 1 << (bits.Len(uint(n)) - 1),
	}
}

// 新增 num 個 val，其中 val 離散化後的值為 i（i 從 1 開始）
// 如果 num < 0，表示減少 -num 個 val
// 注意 val = sorted[i-1]，無需手動傳入
func (f *fenwick) update(i, num int) {
	val := f.sorted[i-1]
	for ; i < len(f.t); i += i & -i {
		f.t[i].cnt += num
		f.t[i].sum += num * val
	}
}

// 返回第 k 小的數（k 從 1 開始）
// 如果不存在第 k 小的數，for 迴圈後的 i = len(f.sorted)，下標越界
func (f *fenwick) kth(k int) int {
	i := 0
	for b := f.highBit; b > 0; b >>= 1 {
		if nxt := i | b; nxt < len(f.t) && f.t[nxt].cnt < k {
			k -= f.t[nxt].cnt
			i = nxt
		}
	}
	return f.sorted[i]
}

// 返回前 k 小的數之和（k 從 1 開始）
// 如果不存在第 k 小的數，for 迴圈後的 i = len(f.sorted)，下標越界
func (f *fenwick) preSum(k int) (s int) {
	i := 0
	for b := f.highBit; b > 0; b >>= 1 {
		if nxt := i | b; nxt < len(f.t) && f.t[nxt].cnt < k {
			k -= f.t[nxt].cnt
			s += f.t[nxt].sum
			i = nxt
		}
	}
	// 加上等於第 k 小的數
	s += f.sorted[i] * k
	return
}
