// 模板來源 https://leetcode.cn/discuss/post/3583665/
// 線段樹有兩個下標，一個是線段樹節點的下標，另一個是線段樹維護的區間的下標
// 節點的下標：從 1 開始，如果你想改成從 0 開始，需要把左右兒子下標分別改成 node*2+1 和 node*2+2
// 區間的下標：從 0 開始
template<typename T>
class SegmentTree {
    // 注：也可以去掉 template<typename T>，改在這裡定義 T
    // using T = pair<int, int>;

    int n;
    vector<T> tree;

    // 合併兩個 val
    T merge_val(T a, T b) const {
        return max(a, b); // **根據題目修改**
    }

    // 合併左右兒子的 val 到當前節點的 val
    void maintain(int node) {
        tree[node] = merge_val(tree[node * 2], tree[node * 2 + 1]);
    }

    // 用 a 初始化線段樹
    // 時間複雜度 O(n)
    void build(const vector<T>& a, int node, int l, int r) {
        if (l == r) { // 葉子
            tree[node] = a[l]; // 初始化葉節點的值
            return;
        }
        int m = (l + r) >> 1;
        build(a, node * 2, l, m); // 初始化左子樹
        build(a, node * 2 + 1, m + 1, r); // 初始化右子樹
        maintain(node);
    }

    void update(int node, int l, int r, int i, T val) {
        if (l == r) { // 葉子（到達目標）
            // 如果想直接替換的話，可以寫 tree[node] = val
            tree[node] = merge_val(tree[node], val);
            return;
        }
        int m = (l + r) >> 1;
        if (i <= m) { // i 在左子樹
            update(node * 2, l, m, i, val);
        } else { // i 在右子樹
            update(node * 2 + 1, m + 1, r, i, val);
        }
        maintain(node);
    }

    T query(int node, int l, int r, int ql, int qr) const {
        if (ql <= l && r <= qr) { // 當前子樹完全在 [ql, qr] 內
            return tree[node];
        }
        int m = (l + r) >> 1;
        if (qr <= m) { // [ql, qr] 與右子樹無交集，僅需遞迴左子樹
            return query(node * 2, l, m, ql, qr);
        }
        if (ql > m) { // [ql, qr] 與左子樹無交集，僅需遞迴右子樹
            return query(node * 2 + 1, m + 1, r, ql, qr);
        }
        // [ql, qr] 與左右子樹均有交集，分別遞迴，然後合併結果
        T l_res = query(node * 2, l, m, ql, qr);
        T r_res = query(node * 2 + 1, m + 1, r, ql, qr);
        return merge_val(l_res, r_res);
    }

public:
    // 線段樹維護一個長為 n 的陣列（下標從 0 到 n-1），元素初始值為 init_val
    SegmentTree(int n, T init_val) : SegmentTree(vector<T>(n, init_val)) {}

    // 線段樹維護陣列 a
    SegmentTree(const vector<T>& a) : n(a.size()), tree(2 << bit_width(a.size() - 1)) {
        build(a, 1, 0, n - 1);
    }

    // 更新 a[i] 為 merge_val(a[i], val)
    // 時間複雜度 O(log n)
    void update(int i, T val) {
        update(1, 0, n - 1, i, val);
    }

    // 返回用 merge_val 合併所有 a[i] 的計算結果，其中 i 在閉區間 [ql, qr] 中
    // 時間複雜度 O(log n)
    T query(int ql, int qr) const {
        return query(1, 0, n - 1, ql, qr);
    }

    // 獲取 a[i] 的值
    // 時間複雜度 O(log n)
    T get(int i) const {
        return query(1, 0, n - 1, i, i);
    }
};

int main() {
