// 區間的下標：從 0 開始
type seg []struct {
    val int // **根據題目修改**
}

// 合併兩個 val
func (seg) mergeVal(a, b int) int {
    return max(a, b) // **根據題目修改**
}

// 線段樹維護一個長為 n 的陣列（下標從 0 到 n-1），元素初始值為 initVal
func newSegmentTree(n int, initVal int) seg {
