        t[node].val = a[l] // 初始化葉節點的值
        return
    }
    m := (l + r) >> 1
    t.build(a, node*2, l, m) // 初始化左子樹
    t.build(a, node*2+1, m+1, r) // 初始化右子樹
    t.maintain(node)
