    m := (l + r) >> 1
    if qr <= m { // [ql, qr] 與右子樹無交集，僅需遞迴左子樹
        return t.query(node*2, l, m, ql, qr)
    }
    if ql > m { // [ql, qr] 與左子樹無交集，僅需遞迴右子樹
        return t.query(node*2+1, m+1, r, ql, qr)
    }
    // [ql, qr] 與左右子樹均有交集，分別遞迴，然後合併結果
    lRes := t.query(node*2, l, m, ql, qr)
    rRes := t.query(node*2+1, m+1, r, ql, qr)
    return t.mergeVal(lRes, rRes)
}
```

把任意區間用 $\mathcal{O}(\log n)$ 個區間表示，線段樹的每個節點記錄對應區間的資訊。

- **詢問**：把詢問區間拆分成 $\mathcal{O}(\log n)$ 個區間，對應著線段樹的 $\mathcal{O}(\log n)$ 個節點，把這 $\mathcal{O}(\log n)$ 個節點的資訊合併，即為答案。
- **區間更新**：仍然是拆分成 $\mathcal{O}(\log n)$ 個區間，對應著線段樹的 $\mathcal{O}(\log n)$ 個節點。但對於其中的非葉節點，不把更新的內容往下傳遞給子節點，而是記錄「發生了更新，內容為 xxx」，把更新的內容記錄下來。直到後續的詢問或更新操作，需要訪問或修改更下面的子節點資訊時，才把更新的內容往下傳。

基礎模板程式碼如下。為方便入門理解，我沒有做複雜封裝。更通用的寫法可以參考 AtCoder Library 的 [lazysegtree.hpp](https://github.com/atcoder/ac-library/blob/master/atcoder/lazysegtree.hpp)。

```py [sol-Python3]
# 模板來源 https://leetcode.cn/discuss/post/3583665/
class Node:
    __slots__ = 'val', 'todo'

class LazySegmentTree:
    # 懶標記初始值
    _TODO_INIT = 0  # **根據題目修改**

    def __init__(self, arr, default=0):
        # 線段樹維護一個長為 n 的陣列（下標從 0 到 n-1）
        # arr 可以是 list 或者 int
        # 如果 arr 是 int，視作陣列大小，預設值為 default
        if isinstance(arr, int):
            arr = [default] * arr
        n = len(arr)
        self._n = n
        self._tree = [Node() for _ in range(2 << (n - 1).bit_length())]
        self._build(arr, 1, 0, n - 1)

    # 合併兩個 val
    def _merge_val(self, a: int, b: int) -> int:
        return a + b  # **根據題目修改**

    # 合併兩個懶標記
    def _merge_todo(self, a: int, b: int) -> int:
        return a + b  # **根據題目修改**

    # 把懶標記作用到 node 子樹（本例為區間加）
    def _apply(self, node: int, l: int, r: int, todo: int) -> None:
        cur = self._tree[node]
        # 計算 tree[node] 區間的整體變化
        cur.val += todo * (r - l + 1)  # **根據題目修改**
        cur.todo = self._merge_todo(todo, cur.todo)

    # 把當前節點的懶標記下傳給左右兒子
    def _spread(self, node: int, l: int, r: int) -> None:
        todo = self._tree[node].todo
        if todo == self._TODO_INIT:  # 沒有需要下傳的資訊
            return
        m = (l + r) // 2
        self._apply(node * 2, l, m, todo)
        self._apply(node * 2 + 1, m + 1, r, todo)
        self._tree[node].todo = self._TODO_INIT  # 下傳完畢

    # 合併左右兒子的 val 到當前節點的 val
    def _maintain(self, node: int) -> None:
        self._tree[node].val = self._merge_val(self._tree[node * 2].val, self._tree[node * 2 + 1].val)

    # 用 a 初始化線段樹
    # 時間複雜度 O(n)
    def _build(self, a: List[int], node: int, l: int, r: int) -> None:
        self._tree[node].todo = self._TODO_INIT
        if l == r:  # 葉子
            self._tree[node].val = a[l]  # 初始化葉節點的值
            return
        m = (l + r) // 2
        self._build(a, node * 2, l, m)  # 初始化左子樹
        self._build(a, node * 2 + 1, m + 1, r)  # 初始化右子樹
        self._maintain(node)

    def _update(self, node: int, l: int, r: int, ql: int, qr: int, f: int) -> None:
        if ql <= l and r <= qr:  # 當前子樹完全在 [ql, qr] 內
            self._apply(node, l, r, f)
            return
        self._spread(node, l, r)
        m = (l + r) // 2
        if ql <= m:  # 更新左子樹
            self._update(node * 2, l, m, ql, qr, f)
        if qr > m:  # 更新右子樹
            self._update(node * 2 + 1, m + 1, r, ql, qr, f)
        self._maintain(node)

    def _query(self, node: int, l: int, r: int, ql: int, qr: int) -> int:
        if ql <= l and r <= qr:  # 當前子樹完全在 [ql, qr] 內
            return self._tree[node].val
        self._spread(node, l, r)
        m = (l + r) // 2
        if qr <= m:  # [ql, qr] 與右子樹無交集，僅需遞迴左子樹
            return self._query(node * 2, l, m, ql, qr)
        if ql > m:  # [ql, qr] 與左子樹無交集，僅需遞迴右子樹
            return self._query(node * 2 + 1, m + 1, r, ql, qr)
        # [ql, qr] 與左右子樹均有交集，分別遞迴，然後合併結果
        l_res = self._query(node * 2, l, m, ql, qr)
        r_res = self._query(node * 2 + 1, m + 1, r, ql, qr)
        return self._merge_val(l_res, r_res)

    # 用 f 更新 [ql, qr] 中的每個 a[i]
    # 0 <= ql <= qr <= n-1
    # 時間複雜度 O(log n)
    def update(self, ql: int, qr: int, f: int) -> None:
        self._update(1, 0, self._n - 1, ql, qr, f)

    # 返回用 _merge_val 合併所有 a[i] 的計算結果，其中 i 在閉區間 [ql, qr] 中
    # 0 <= ql <= qr <= n-1
    # 時間複雜度 O(log n)
    def query(self, ql: int, qr: int) -> int:
        return self._query(1, 0, self._n - 1, ql, qr)
