class LazySegmentTree {
    // 懶標記初始值
    private static final long TODO_INIT = 0; // **根據題目修改**

    private static final class Node {
        long val; // **根據題目修改**
        long todo;
    }

    // 合併兩個 val
    private long mergeVal(long a, long b) {
        return a + b; // **根據題目修改**
    }

    // 合併兩個懶標記
    private long mergeTodo(long a, long b) {
        return a + b; // **根據題目修改**
    }

    // 把懶標記作用到 node 子樹（本例為區間加）
    private void apply(int node, int l, int r, long todo) {
        Node cur = tree[node];
        // 計算 tree[node] 區間的整體變化
        cur.val += todo * (r - l + 1); // **根據題目修改**
        cur.todo = mergeTodo(todo, cur.todo);
    }

    private final int n;
    private final Node[] tree;

    // 線段樹維護一個長為 n 的陣列（下標從 0 到 n-1），元素初始值為 initVal
    public LazySegmentTree(int n, long initVal) {
        this.n = n;
        long[] a = new long[n];
        Arrays.fill(a, initVal);
        tree = new Node[2 << (32 - Integer.numberOfLeadingZeros(n - 1))];
        build(a, 1, 0, n - 1);
    }

    // 線段樹維護陣列 a
    public LazySegmentTree(long[] a) {
        n = a.length;
        tree = new Node[2 << (32 - Integer.numberOfLeadingZeros(n - 1))];
        build(a, 1, 0, n - 1);
    }

    // 用 f 更新 [ql, qr] 中的每個 a[i]
    // 0 <= ql <= qr <= n-1
    // 時間複雜度 O(log n)
    public void update(int ql, int qr, long f) {
        update(1, 0, n - 1, ql, qr, f);
    }

    // 返回用 mergeVal 合併所有 a[i] 的計算結果，其中 i 在閉區間 [ql, qr] 中
    // 0 <= ql <= qr <= n-1
    // 時間複雜度 O(log n)
    public long query(int ql, int qr) {
        return query(1, 0, n - 1, ql, qr);
    }

    // 把當前節點的懶標記下傳給左右兒子
    private void spread(int node, int l, int r) {
        long todo = tree[node].todo;
        if (todo == TODO_INIT) { // 沒有需要下傳的資訊
            return;
        }
        int m = (l + r) >>> 1;
        apply(node * 2, l, m, todo);
        apply(node * 2 + 1, m + 1, r, todo);
        tree[node].todo = TODO_INIT; // 下傳完畢
    }

    // 合併左右兒子的 val 到當前節點的 val
    private void maintain(int node) {
        tree[node].val = mergeVal(tree[node * 2].val, tree[node * 2 + 1].val);
    }

    // 用 a 初始化線段樹
    // 時間複雜度 O(n)
    private void build(long[] a, int node, int l, int r) {
        tree[node] = new Node();
        tree[node].todo = TODO_INIT;
        if (l == r) { // 葉子
            tree[node].val = a[l]; // 初始化葉節點的值
            return;
        }
        int m = (l + r) >>> 1;
        build(a, node * 2, l, m); // 初始化左子樹
        build(a, node * 2 + 1, m + 1, r); // 初始化右子樹
        maintain(node);
    }

    private void update(int node, int l, int r, int ql, int qr, long f) {
        if (ql <= l && r <= qr) { // 當前子樹完全在 [ql, qr] 內
            apply(node, l, r, f);
            return;
        }
        spread(node, l, r);
        int m = (l + r) >>> 1;
        if (ql <= m) { // 更新左子樹
            update(node * 2, l, m, ql, qr, f);
        }
        if (qr > m) { // 更新右子樹
            update(node * 2 + 1, m + 1, r, ql, qr, f);
        }
        maintain(node);
    }

    private long query(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) { // 當前子樹完全在 [ql, qr] 內
            return tree[node].val;
        }
        spread(node, l, r);
        int m = (l + r) >>> 1;
        if (qr <= m) { // [ql, qr] 與右子樹無交集，僅需遞迴左子樹
            return query(node * 2, l, m, ql, qr);
        }
        if (ql > m) { // [ql, qr] 與左子樹無交集，僅需遞迴右子樹
            return query(node * 2 + 1, m + 1, r, ql, qr);
        }
        // [ql, qr] 與左右子樹均有交集，分別遞迴，然後合併結果
        long lRes = query(node * 2, l, m, ql, qr);
        long rRes = query(node * 2 + 1, m + 1, r, ql, qr);
        return mergeVal(lRes, rRes);
    }
}
