```go [sol-Go]
type sparseTable[T any] struct {
    st [][]T
    op func(T, T) T
}

// 時間複雜度 O(n * log n)
func newSparseTable[T any](nums []T, op func(T, T) T) sparseTable[T] {
    n := len(nums)
    w := bits.Len(uint(n))
    st := make([][]T, w)
    for i := range st {
        st[i] = make([]T, n)
    }
    copy(st[0], nums)
    for i := 1; i < w; i++ {
        for j := range n - 1<<i + 1 {
            st[i][j] = op(st[i-1][j], st[i-1][j+1<<(i-1)])
        }
    }
    return sparseTable[T]{st, op}
}

// [l, r) 左閉右開，下標從 0 開始
// 返回 op(nums[l:r])
// 時間複雜度 O(1)
func (s sparseTable[T]) query(l, r int) T {
    k := bits.Len(uint(r-l)) - 1
    return s.op(s.st[k][l], s.st[k][r-1<<k])
}

// 使用方法舉例
func main() {
    nums := []int{3, 1, 4, 1, 5, 9, 2, 6}
    st := newSparseTable(nums, func(a, b int) int { return max(a, b) })
    fmt.Println(st.query(0, 5)) // 5
    fmt.Println(st.query(1, 1)) // 錯誤：必須保證 l < r
}
